unit.content:
/* Marlow Street Bakery
   One stylesheet. No image files, no webfonts, nothing loaded from another site.
   Palette: cream crumb, dark crust, rust from the cuts in the loaf. */

:root {
  --cream: #faf3e6;
  --cream-deep: #f1e5d0;
  --wash-order: #f2dcc2;
  --crust: #32200f;
  --crust-soft: #6d5442;
  --accent: #b0521f;
  --accent-deep: #8d3f14;
  --accent-press: #74330f;
  --cream-ink: #fff6ea;
  --rule: rgba(50, 32, 15, 0.16);
  --shell: 68rem;
  --font-sans: "Avenir Next", "Segoe UI Variable Display", "Segoe UI", "Helvetica Neue", system-ui, -apple-system, sans-serif;
  color-scheme: light;
}

*, *::before, *::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 1.0625rem;
  line-height: 1.55;
  color: var(--crust);
  background-color: var(--cream);
  /* A warm field rather than one flat fill: light falls on the counter from the top. */
  background-image:
    radial-gradient(90% 55% at 50% 0%, rgba(255, 252, 244, 0.85), rgba(255, 252, 244, 0) 72%),
    radial-gradient(65% 45% at 100% 100%, rgba(176, 82, 31, 0.06), rgba(176, 82, 31, 0) 70%);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, p, dl, dd, address { margin: 0; }
ul { margin: 0; padding: 0; list-style: none; }

::selection { background: rgba(176, 82, 31, 0.2); }

/* One shell so every band lines up, while its colour still runs edge to edge. */
.masthead,
.menu,
.hours,
.order,
.visit,
.footer {
  padding-inline: max(1.25rem, calc((100% - var(--shell)) / 2));
}

section[id] { scroll-margin-top: 1.5rem; }

@media (prefers-reduced-motion: no-preference) {
  html { scroll-behavior: smooth; }
}

/* ---------------------------------------------------------------- links */

a {
  color: var(--accent-deep);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: color 140ms ease;
}

a:hover { color: var(--accent); text-decoration-thickness: 2px; }
a:active { color: var(--accent-press); }

a:focus-visible {
  outline: 3px solid var(--crust);
  outline-offset: 3px;
  border-radius: 2px;
}

.skip-link {
  position: absolute;
  top: 0;
  left: 1.25rem;
  z-index: 20;
  transform: translateY(-120%);
  padding: 0.7rem 1.1rem;
  background: var(--crust);
  color: var(--cream-ink);
  font-weight: 600;
  text-decoration: none;
  border-radius: 0 0 6px 6px;
  transition: transform 160ms ease, background-color 140ms ease;
}

.skip-link:hover { background: var(--accent-deep); color: #fff8ef; transform: translateY(0); }
.skip-link:active { background: var(--accent-press); }
.skip-link:focus { transform: translateY(0); }

/* -------------------------------------------------------------- masthead */

.masthead {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr);
  grid-template-areas:
    "nav nav"
    "text loaf";
  align-items: end;
  gap: clamp(1.25rem, 2.5vw, 2rem) clamp(2rem, 5vw, 4rem);
  padding-block: clamp(1.5rem, 3vw, 2.25rem) clamp(2rem, 5vw, 3.5rem);
  border-bottom: 1px solid var(--rule);
  /* Warmth gathers around the loaf on the right, as it does near the oven. */
  background-image:
    radial-gradient(70% 95% at 84% 62%, rgba(176, 82, 31, 0.11), rgba(176, 82, 31, 0) 66%),
    linear-gradient(180deg, #fdf8ee 0%, var(--cream) 100%);
}

.site-nav { grid-area: nav; }

.site-nav__list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 1.6rem;
}

.site-nav__link {
  display: inline-block;
  padding-block: 0.3rem;
  color: var(--crust-soft);
  font-size: 0.98rem;
  font-weight: 600;
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: color 140ms ease, border-color 140ms ease;
}

.site-nav__link:hover { color: var(--crust); border-bottom-color: var(--accent); }
.site-nav__link:active { color: var(--accent-deep); border-bottom-color: var(--accent-deep); }

.masthead__text {
  grid-area: text;
  align-self: end;
  padding-bottom: clamp(0.5rem, 2vw, 1.5rem);
}

.masthead__name {
  font-size: clamp(2.6rem, 7.4vw, 5rem);
  font-weight: 800;
  line-height: 0.95;
  letter-spacing: -0.03em;
  text-wrap: balance;
}

.masthead__lede {
  margin-top: clamp(0.85rem, 2vw, 1.35rem);
  max-width: 32ch;
  font-size: clamp(1.05rem, 1.5vw, 1.25rem);
  line-height: 1.5;
  color: var(--crust-soft);
  text-wrap: pretty;
}

.masthead__loaf { grid-area: loaf; }

.loaf {
  display: block;
  width: 100%;
  height: auto;
  color: var(--crust);
}

.loaf__scores { stroke: var(--accent); }

/* ----------------------------------------------------------------- menu */

.menu {
  padding-block: clamp(3rem, 7vw, 5.5rem);
  background: var(--cream-deep);
  border-bottom: 1px solid var(--rule);
}

.menu__title,
.hours__title,
.visit__title {
  font-size: clamp(1.7rem, 3.6vw, 2.5rem);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.025em;
  max-width: 24ch;
}

.menu__groups {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
  gap: clamp(1.75rem, 4vw, 3.5rem);
  margin-top: clamp(2rem, 4vw, 3rem);
}

.menu__group-title {
  padding-bottom: 0.6rem;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.005em;
  border-bottom: 2px solid var(--crust);
}

.price-list { margin-top: 0.35rem; }

.price-list__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1.25rem;
  padding-block: 0.6rem;
}

.price-list__row + .price-list__row { border-top: 1px solid var(--rule); }

.price-list__name { font-size: 1.0625rem; }

.price-list__price {
  flex: none;
  min-width: 4.25rem;
  text-align: right;
  font-size: 1.0625rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.menu__note {
  margin-top: clamp(1.75rem, 3.5vw, 2.75rem);
  max-width: 46ch;
  font-size: 0.98rem;
  color: var(--crust-soft);
}

/* ---------------------------------------------------------------- hours */

.hours { padding-block: clamp(3rem, 7vw, 5.5rem); }

/* The open or closed line is written into this element by app.js. */
.hours__now,
#open-now {
  margin-top: clamp(1rem, 2vw, 1.4rem);
  font-size: clamp(1.2rem, 2.4vw, 1.5rem);
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--accent);
}

.hours__now.is-closed,
.hours__now--closed { color: var(--crust-soft); }

.hours__list {
  margin-top: clamp(1.75rem, 3vw, 2.5rem);
  max-width: 42rem;
}

.hours__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1.25rem;
  padding-block: 0.85rem;
}

.hours__row + .hours__row { border-top: 1px solid var(--rule); }

.hours__days { font-size: 1.05rem; font-weight: 700; }

.hours__time {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--crust-soft);
}

.hours__row--closed .hours__days { font-weight: 600; color: var(--crust-soft); }

/* ---------------------------------------------------------------- order */

.order {
  padding-block: clamp(3.5rem, 8vw, 6rem);
  background: var(--wash-order);
}

.order__title {
  max-width: 20ch;
  font-size: clamp(1.9rem, 4.6vw, 3.25rem);
  font-weight: 800;
  line-height: 1.02;
  letter-spacing: -0.03em;
  text-wrap: balance;
}

.order__text {
  margin-top: clamp(1rem, 2vw, 1.4rem);
  max-width: 56ch;
  font-size: clamp(1.05rem, 1.5vw, 1.15rem);
}

.order__action { margin-top: clamp(1.75rem, 3vw, 2.5rem); }

.button {
  display: inline-block;
  padding: 0.95rem 1.6rem;
  background: var(--accent);
  color: var(--cream-ink);
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.005em;
  text-decoration: none;
  border-radius: 6px;
  box-shadow: 0 12px 22px -16px rgba(50, 32, 15, 0.9);
  transition: background-color 140ms ease, transform 120ms ease, box-shadow 140ms ease, color 140ms ease;
}

.button:hover {
  background: var(--accent-deep);
  color: #fff8ef;
  transform: translateY(-1px);
  box-shadow: 0 16px 26px -16px rgba(50, 32, 15, 0.9);
}

.button:active {
  background: var(--accent-press);
  transform: translateY(1px);
  box-shadow: 0 6px 14px -12px rgba(50, 32, 15, 0.9);
}

.button:focus-visible {
  outline: 3px solid var(--crust);
  outline-offset: 3px;
}

/* ---------------------------------------------------------------- visit */

.visit { padding-block: clamp(3rem, 7vw, 5.5rem); }

.visit__address {
  display: grid;
  gap: 0.3rem;
  justify-items: start;
  margin-top: clamp(1.25rem, 2.5vw, 1.75rem);
  font-style: normal;
}

.visit__street {
  font-size: clamp(1.35rem, 3vw, 1.9rem);
  font-weight: 700;
  letter-spacing: -0.02em;
}

.visit__landmark { color: var(--crust-soft); }

.visit__phone {
  margin-top: 0.6rem;
  font-size: 1.15rem;
  font-weight: 700;
}

.visit__text {
  margin-top: clamp(1.75rem, 3vw, 2.5rem);
  max-width: 52ch;
  color: var(--crust-soft);
}

/* --------------------------------------------------------------- footer */

.footer {
  padding-block: clamp(2rem, 4vw, 3rem);
  background: var(--cream-deep);
  border-top: 1px solid var(--rule);
  font-size: 0.98rem;
  color: var(--crust-soft);
}

.footer__starter {
  max-width: 46ch;
  font-weight: 600;
  color: var(--crust);
}

.footer__details { margin-top: 0.85rem; }

/* ------------------------------------------------- tablet and narrower */

@media (max-width: 820px) {
  .masthead {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "nav"
      "text"
      "loaf";
    align-items: start;
  }

  .masthead__name { font-size: clamp(2.5rem, 10vw, 4rem); }
  .masthead__lede { max-width: 38ch; }
  .masthead__loaf { margin-top: clamp(0.75rem, 3vw, 1.5rem); }
  .masthead__text { padding-bottom: 0; }
}

/* ------------------------------------------------------ phone at 390px */

@media (max-width: 520px) {
  body { font-size: 1rem; line-height: 1.5; }

  .masthead { padding-block: 1.25rem 2rem; }
  .masthead__name { font-size: clamp(2.1rem, 12vw, 2.9rem); }
  .masthead__lede { margin-top: 0.75rem; font-size: 1.05rem; }
  .masthead__loaf { margin-top: 0.5rem; }

  .site-nav__list { gap: 0.2rem 1.1rem; }
  .site-nav__link { font-size: 0.95rem; }

  .menu { padding-block: 2.5rem; }
  .menu__groups { grid-template-columns: minmax(0, 1fr); gap: 2rem; margin-top: 1.5rem; }
  .price-list__row { padding-block: 0.7rem; }
  .price-list__name, .price-list__price { font-size: 1rem; }
  .price-list__price { min-width: 3.75rem; }

  .hours { padding-block: 2.5rem; }
  .hours__title, .menu__title, .visit__title { font-size: clamp(1.55rem, 7vw, 2rem); }
  .hours__row {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.15rem;
    padding-block: 0.9rem;
  }

  .order { padding-block: 2.75rem; }
  .order__title { font-size: clamp(1.7rem, 8.5vw, 2.2rem); }
  .order__action { margin-top: 1.5rem; }

  .button {
    display: block;
    padding: 1.05rem 1.25rem;
    text-align: center;
  }

  .visit { padding-block: 2.5rem; }
  .footer { padding-block: 1.75rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

