/* Marlow Street Bakery
   One small script: it reads the visitor's own clock and writes a plain
   "Open now" or "Closed now" line into #open-now, using the same hours
   that are printed in the list beside it.
   The page is complete without this file, so nothing here is required
   in order to read the hours, the menu or anything else. */

(function () {
  "use strict";

  var CHECK_EVERY = 60000; // one minute is close enough for a bakery counter

  /* The published hours, from Sunday first, the way Date.getDay() counts days.
     Times are counted in minutes from midnight: 420 is 7:00 am, 900 is 3:00 pm. */
  var WEEK = [
    { name: "Sunday",    opens: 8 * 60,  closes: 14 * 60 }, // 8:00 am to 2:00 pm
    { name: "Monday",    opens: null,    closes: null },    // closed
    { name: "Tuesday",   opens: 7 * 60,  closes: 15 * 60 }, // 7:00 am to 3:00 pm
    { name: "Wednesday", opens: 7 * 60,  closes: 15 * 60 },
    { name: "Thursday",  opens: 7 * 60,  closes: 15 * 60 },
    { name: "Friday",    opens: 7 * 60,  closes: 15 * 60 },
    { name: "Saturday",  opens: 8 * 60,  closes: 14 * 60 }  // 8:00 am to 2:00 pm
  ];

  /* 420 becomes "7:00 am". */
  function clock(minutes) {
    var hours = Math.floor(minutes / 60);
    var rest = minutes % 60;
    var suffix = hours < 12 ? "am" : "pm";
    var hour12 = hours % 12 === 0 ? 12 : hours % 12;
    return hour12 + ":" + (rest < 10 ? "0" + rest : String(rest)) + " " + suffix;
  }

  /* The next day the shop opens, looking up to a week ahead. */
  function nextOpening(dayIndex) {
    for (var step = 1; step <= 7; step++) {
      var day = WEEK[(dayIndex + step) % 7];
      if (day.opens !== null) {
        return { day: day, isTomorrow: step === 1 };
      }
    }
    return null;
  }

  /* One plain sentence, and whether the shop is open at that moment. */
  function lineFor(now) {
    var today = WEEK[now.getDay()];
    var minutes = now.getHours() * 60 + now.getMinutes();

    if (today.opens !== null && minutes >= today.opens && minutes < today.closes) {
      return { text: "Open now until " + clock(today.closes) + ".", open: true };
    }

    if (today.opens !== null && minutes < today.opens) {
      return { text: "Closed now. We open at " + clock(today.opens) + " today.", open: false };
    }

    var next = nextOpening(now.getDay());
    if (!next) {
      return { text: "Closed now.", open: false };
    }

    var when = next.isTomorrow ? "tomorrow" : "on " + next.day.name;
    return {
      text: "Closed now. We open " + when + " at " + clock(next.day.opens) + ".",
      open: false
    };
  }

  function start() {
    var line = document.getElementById("open-now");
    if (!line) {
      return;
    }

    function update() {
      var result = lineFor(new Date());
      line.textContent = result.text;
      /* styles.css dims the line while the shop is shut. */
      line.classList.toggle("is-closed", !result.open);
    }

    update();
    window.setInterval(update, CHECK_EVERY);

    /* Coming back to the tab after a while should show the right line again. */
    document.addEventListener("visibilitychange", function () {
      if (!document.hidden) {
        update();
      }
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();

