  gap: clamp(1.25rem, 2.6vw, 2rem);
  margin-top: clamp(2rem, 4vw, 3rem);
  align-items: start;
}

/* Each part of the menu is its own soft, round card. */
.menu__group {
  padding: clamp(1.35rem, 2.4vw, 1.85rem);
  background: var(--card);
  border: 1px solid rgba(50, 32, 15, 0.07);
  border-radius: 24px;
  box-shadow: 0 20px 32px -28px rgba(50, 32, 15, 0.75);
}

.menu__group-title {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.005em;
}

/* The prices sit together in a rounder, slightly deeper panel so they
   read as one block at a glance. */
.price-list {
  margin-top: 1rem;
  padding: 0.25rem 0.95rem;
  background: rgba(241, 229, 208, 0.6);
  border-radius: 16px;
}

.price-list__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1.25rem;
  padding-block: 0.7rem;
}

.price-list__row + .price-list__row { border-top: 1px solid var(--rule); }

.price-list__name { font-size: 1.0625rem; }

.price-list__price {
  flex: none;
  min-width: 4.25rem;
  text-align: right;
  font-size: 1.0625rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.menu__note {
  margin-top: clamp(1.75rem, 3.5vw, 2.75rem);
  max-width: 46ch;
  font-size: 0.98rem;
  color: var(--crust-soft);
}

/* ---------------------------------------------------------------- hours */

.hours { padding-block: clamp(3rem, 7vw, 5.5rem); }

/* The open or closed line is written into this element by app.js. */
.hours__now,
#open-now {
  margin-top: clamp(1rem, 2vw, 1.4rem);
  font-size: clamp(1.2rem, 2.4vw, 1.5rem);
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--accent);
}

.hours__now.is-closed,
.hours__now--closed { color: var(--crust-soft); }

.hours__list {
  margin-top: clamp(1.75rem, 3vw, 2.5rem);
  max-width: 42rem;
}

.hours__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1.25rem;
  padding-block: 0.85rem;
}

.hours__row + .hours__row { border-top: 1px solid var(--rule); }

.hours__days { font-size: 1.05rem; font-weight: 700; }

.hours__time {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--crust-soft);
}

.hours__row--closed .hours__days { font-weight: 600; color: var(--crust-soft); }

/* ---------------------------------------------------------------- order */

.order {
  padding-block: clamp(3.5rem, 8vw, 6rem);
  background: var(--wash-order);
}

.order__title {
  max-width: 20ch;
  font-size: clamp(1.9rem, 4.6vw, 3.25rem);
  font-weight: 800;
  line-height: 1.02;
  letter-spacing: -0.03em;
  text-wrap: balance;
}

.order__text {
  margin-top: clamp(1rem, 2vw, 1.4rem);
  max-width: 56ch;
  font-size: clamp(1.05rem, 1.5vw, 1.15rem);
}

.order__action { margin-top: clamp(1.75rem, 3vw, 2.5rem); }

.button {
  display: inline-block;
  padding: 0.95rem 1.6rem;
  background: var(--accent);
  color: var(--cream-ink);
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.005em;
  text-decoration: none;
  border-radius: 999px;
  box-shadow: 0 12px 22px -16px rgba(50, 32, 15, 0.9);
  transition: background-color 140ms ease, transform 120ms ease, box-shadow 140ms ease, color 140ms ease;
}

.button:hover {
  background: var(--accent-deep);
  color: #fff8ef;
  transform: translateY(-1px);
  box-shadow: 0 16px 26px -16px rgba(50, 32, 15, 0.9);
}

.button:active {
  background: var(--accent-press);
  transform: translateY(1px);
  box-shadow: 0 6px 14px -12px rgba(50, 32, 15, 0.9);
}

.button:focus-visible {
  outline: 3px solid var(--crust);
  outline-offset: 3px;
}

/* ---------------------------------------------------------------- visit */

.visit { padding-block: clamp(3rem, 7vw, 5.5rem); }

.visit__address {
  display: grid;
  gap: 0.3rem;
  justify-items: start;
  margin-top: clamp(1.25rem, 2.5vw, 1.75rem);
  font-style: normal;
}

.visit__street {
  font-size: clamp(1.35rem, 3vw, 1.9rem);
  font-weight: 700;
  letter-spacing: -0.02em;
}

.visit__landmark { color: var(--crust-soft); }

.visit__phone {
  margin-top: 0.6rem;
  font-size: 1.15rem;
  font-weight: 700;
}

.visit__text {
  margin-top: clamp(1.75rem, 3vw, 2.5rem);
  max-width: 52ch;
  color: var(--crust-soft);
}

/* --------------------------------------------------------------- footer */

.footer {
  padding-block: clamp(2rem, 4vw, 3rem);
  background: var(--cream-deep);
  border-top: 1px solid var(--rule);
  font-size: 0.98rem;
  color: var(--crust-soft);
}

.footer__starter {
  max-width: 46ch;
  font-weight: 600;
  color: var(--crust);
}

.footer__details { margin-top: 0.85rem; }

/* ------------------------------------------------- tablet and narrower */

@media (max-width: 820px) {
  .masthead {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "nav"
      "text"
      "loaf";
    align-items: start;
  }

  .masthead__name { font-size: clamp(2.5rem, 10vw, 4rem); }
  .masthead__welcome { max-width: 40ch; }
  .masthead__lede { max-width: 38ch; }
  .masthead__loaf { margin-top: clamp(0.75rem, 3vw, 1.5rem); }
  .masthead__text { padding-bottom: 0; }
}

/* ------------------------------------------------------ phone at 390px */

@media (max-width: 520px) {
  body { font-size: 1rem; line-height: 1.5; }

  .masthead { padding-block: 1.25rem 2rem; }
  .masthead__name { font-size: clamp(2.1rem, 12vw, 2.9rem); }
  .masthead__welcome { margin-top: 0.75rem; font-size: 1.08rem; }
  .masthead__lede { margin-top: 0.6rem; font-size: 1rem; }
  .masthead__loaf { margin-top: 0.5rem; }

  .site-nav__list { gap: 0.2rem 1.1rem; }
  .site-nav__link { font-size: 0.95rem; }

  .menu { padding-block: 2.5rem; }
  .menu__groups { grid-template-columns: minmax(0, 1fr); gap: 1.25rem; margin-top: 1.5rem; }
  .menu__group { padding: 1.25rem 1.15rem; border-radius: 20px; }
  .price-list { padding: 0.2rem 0.8rem; border-radius: 14px; }
  .price-list__row { padding-block: 0.7rem; }
  .price-list__name, .price-list__price { font-size: 1rem; }
  .price-list__price { min-width: 3.75rem; }

  .hours { padding-block: 2.5rem; }
  .hours__title, .menu__title, .visit__title { font-size: clamp(1.55rem, 7vw, 2rem); }
  .hours__row {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.15rem;
    padding-block: 0.9rem;
  }

  .order { padding-block: 2.75rem; }
  .order__title { font-size: clamp(1.7rem, 8.5vw, 2.2rem); }
  .order__action { margin-top: 1.5rem; }

  .button {
    display: block;
    padding: 1.05rem 1.25rem;
    text-align: center;
  }

  .visit { padding-block: 2.5rem; }
  .footer { padding-block: 1.75rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
